package repository

// amountToInt64 keeps the repository boundary explicit: saldo amounts are
// stored as PostgreSQL BIGINT and therefore generated by sqlc as int64.
func amountToInt64(value int) int64 {
	return int64(value)
}

func optionalAmountToInt64(value *int) *int64 {
	if value == nil {
		return nil
	}

	converted := amountToInt64(*value)
	return &converted
}
